    <script>
      function SafeGetValue(obj, path, defaultValue = 'N/A') {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
          if (
            current === undefined ||
            current === null ||
            typeof current !== 'object' ||
            !current.hasOwnProperty(keys[i])
          ) {
            return defaultValue;
          }
          current = current[keys[i]];
        }
        if (current === undefined || current === null) {
          return defaultValue;
        }
        if (Array.isArray(current)) {
          if (current.length > 0) {
            const actualValue = current[0];
            if (typeof actualValue === 'boolean') {
              return actualValue;
            }
            return String(actualValue);
          } else {
            return defaultValue;
          }
        }
        if (typeof current === 'boolean') {
          return current;
        }
        return String(current);
      }

      function updateProgressBar(barId, valueMainId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);

        if (!valueMainDisplay) return;

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;

        valueMainDisplay.innerText = fullDisplayString;

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=\s*->|\s*$)/);
        if (valueMatch) {
          numericValue = parseFloat(valueMatch[1]);
        }

        if (progressBar) {
          numericValue = Math.max(min, Math.min(max, numericValue));
          const range = max - min;
          const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
          progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
          if (color) {
            progressBar.style.backgroundColor = color;
          }
        }
      }

      function updateTextValue(elementId, value) {
        const element = document.getElementById(elementId);
        if (element) {
          element.innerText = value;
        }
      }

      async function initDisplay() {
        try {
          const messages = await getChatMessages(getCurrentMessageId());
          if (!messages || messages.length === 0 || !messages[0].data) {
            return;
          }
          const gameData = messages[0].data;
          const characterData = gameData.stat_data;
          if (!characterData) {
            return;
          }

          const topBar = document.getElementById('top-bar');
          const 血息值 = parseInt(SafeGetValue(characterData, '血息值', 100));
          topBar.className = '';
          if (血息值 >= 70) {
            topBar.classList.add('health-high');
          } else if (血息值 >= 30) {
            topBar.classList.add('health-medium');
          } else if (血息值 >= 1) {
            topBar.classList.add('health-low');
          } else {
            topBar.classList.add('health-critical');
          }
          updateTextValue('world-time', SafeGetValue(characterData, '世界.时间', '--'));
          updateTextValue('world-location', SafeGetValue(characterData, '世界.地点', '--'));
          updateTextValue('world-weather', SafeGetValue(characterData, '世界.天气', '--'));

          const eleanorCard = document.getElementById('eleanor-card');
          const isEleanorPresent = SafeGetValue(characterData, '埃莉诺.参与中', false);
          if (isEleanorPresent === true) {
            eleanorCard.style.display = 'block';
            eleanorCard.classList.remove('absent');
            updateProgressBar(
              'eleanor-affection-bar',
              'eleanor-affection',
              SafeGetValue(characterData, '埃莉诺.好感度', 0),
              0,
              100,
              'var(--eleanor-accent)',
            );
            updateProgressBar(
              'eleanor-hunger-bar',
              'eleanor-hunger',
              SafeGetValue(characterData, '埃莉诺.饥渴度', 0),
              0,
              100,
              'var(--eleanor-accent)',
            );
            updateTextValue('eleanor-expression', SafeGetValue(characterData, '埃莉诺.表情', '--'));
            updateTextValue('eleanor-outfit', SafeGetValue(characterData, '埃莉诺.穿着', '--'));
            updateTextValue('eleanor-action', SafeGetValue(characterData, '埃莉诺.动作', '--'));
            updateTextValue('eleanor-thought', SafeGetValue(characterData, '埃莉诺.想法', '--'));
          } else {
            eleanorCard.style.display = 'block';
            eleanorCard.classList.add('absent');
          }

          const claraCard = document.getElementById('clara-card');
          const isClaraPresent = SafeGetValue(characterData, '克拉拉.参与中', false);
          if (isClaraPresent === true) {
            claraCard.style.display = 'block';
            claraCard.classList.remove('absent');
            updateProgressBar(
              'clara-affection-bar',
              'clara-affection',
              SafeGetValue(characterData, '克拉拉.好感度', 0),
              0,
              100,
              'var(--clara-accent)',
            );
            updateProgressBar(
              'clara-hunger-bar',
              'clara-hunger',
              SafeGetValue(characterData, '克拉拉.饥渴度', 0),
              0,
              100,
              'var(--clara-accent)',
            );
            updateTextValue('clara-expression', SafeGetValue(characterData, '克拉拉.表情', '--'));
            updateTextValue('clara-outfit', SafeGetValue(characterData, '克拉拉.穿着', '--'));
            updateTextValue('clara-action', SafeGetValue(characterData, '克拉拉.动作', '--'));
            updateTextValue('clara-thought', SafeGetValue(characterData, '克拉拉.想法', '--'));
          } else {
            claraCard.style.display = 'block';
            claraCard.classList.add('absent');
          }

          // 根据红链值调整母女名字的发光强度
          const redChainValue = parseInt(SafeGetValue(characterData, '红链值', 0));
          const eleanorHeader = document.querySelector('#eleanor-card .card-header');
          const claraHeader = document.querySelector('#clara-card .card-header');

          if (eleanorHeader && claraHeader) {
            // 红链值低时：埃莉诺发光弱，克拉拉发光强
            // 红链值高时：埃莉诺发光强，克拉拉发光弱
            const eleanorGlow = Math.max(0.1, redChainValue / 100); // 0.1-1.0
            const claraGlow = Math.max(0.1, (100 - redChainValue) / 100); // 1.0-0.1

            eleanorHeader.style.textShadow = `0 0 15px rgba(74, 144, 226, ${eleanorGlow})`;
            claraHeader.style.textShadow = `0 0 15px rgba(255, 105, 180, ${claraGlow})`;
          }
        } catch (error) {
          console.error('状态栏加载出错:', error);
        }
      }

      document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
